fn solve(a: i8, b: i8) -> (i8, i8) {
    // Number of days pairing one of each type is simply the minimum of the two counts.
    let different_type_days = a.min(b);

    // After that, the remaining difference in counts is |a - b|.
    // Each same-type pair consumes 2 items, so we take integer division by 2.
    let same_type_days = (a - b).abs() / 2;

    (different_type_days, same_type_days)
}

fn main() {
    // Example usage
    let examples = [(5, 3), (4, 4), (1, 10), (7, 2)];
    for &(a, b) in &examples {
        let (diff_days, same_days) = solve(a, b);
        println!(
            "For counts ({}, {}): different-type days = {}, same-type days = {}",
            a, b, diff_days, same_days
        );
    }
}